WITH flattened_attrs AS (SELECT id, log_ts, status_code, context, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, context['trace'] AS trace, SIZE(context) AS num_context FROM app_logs) SELECT *, FIRST_VALUE(num_context) IGNORE NULLS OVER w_running AS first_known_num_context, FIRST_VALUE(num_context) IGNORE NULLS OVER w_running AS first_known_num_context_2, AVG(num_context) OVER (ORDER BY status_code, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS num_context_avg_5_prior, LAG(num_context, 1) OVER (ORDER BY num_context, id) AS prev_num_context FROM flattened_attrs WINDOW w_running AS (ORDER BY num_context, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
